void CreateListR(T a[], int n) { 
if (a && n > 0) {
head = new ListNode<T>(a[0]);
ListNode<T>* tail = head;
for (int i = 1; i < n; i++) {
ListNode<T>* newNode = new ListNode<T>(a[i]);
tail->next = newNode;
tail = newNode;
}
tail->next = head; 
}
}
// 连接两个链表
void ConnectLists(LinkedList<T>& list2) { 
if (list2.head) {
if (!head) {
head = list2.head;
} else {
ListNode<T>* tail1 = head;
while (tail1->next != head) {
tail1 = tail1->next;
}
ListNode<T>* tail2 = list2.head;
while (tail2->next != list2.head) {
tail2 = tail2->next;
}
tail1->next = list2.head;
tail2->next = head;
list2.head = NULL;
}
}
}
};
